def pnum(t):
    t = t.strip().rstrip(',')
    if re.fullmatch(r'[0-9A-Fa-f]{1,2}[hH]', t): return int(t[:-1], 16)
    return int(t, 0)

def reg(t):
    m = re.fullmatch(r'[Vv]([0-9A-Fa-f])', t.strip())
    if not m: raise ValueError('not a reg: ' + repr(t))
    return int(m.group(1), 16)

def tokenize(rest):
    return [a for a in re.split(r'[,\s]+', rest.strip()) if a]

# ---- pass 1: labels + sizes ----
lines, labels, addr = [], {}, ORG
for raw in ASM.splitlines():
    s = raw.split(';')[0].strip()
    if not s: continue
    label, rest = None, s
    m = re.match(r'^([A-Za-z_]\w*)\s*:\s*(.*)$', s)
    if m: label, rest = m.group(1), m.group(2)
